(1202058, 151486, 33182, '<td valign="top">Personally, I think the shadows are a little distracting. Makes the "white" background grey. Nice sharp picture.</td>', 'Personally, I think the shadows are a little distracting. Makes the "white" background grey. Nice sharp picture.', '2005-03-02 00:03:24.000000', NULL, 1),
(1202069, 150516, 33182, '<td valign="top">The snow is light, the baground is "white" but the trees make this just too dark of an image for me.</td>', 'The snow is light, the baground is "white" but the trees make this just too dark of an image for me.', '2005-03-02 00:05:13.000000', NULL, 1),
(1202073, 150406, 33182, '<td valign="top">I know it sounds nit-picky, but to me your subject seems "bright" not light.</td>', 'I know it sounds nit-picky, but to me your subject seems "bright" not light.', '2005-03-02 00:06:36.000000', NULL, 1),
(1202075, 151700, 32236, '<td valign="top">Interesting textures.</td>', 'Interesting textures.', '2005-03-02 00:07:06.000000', NULL, 1),
