(1202351, 151567, 33182, '<td valign="top">My wife would love that bunny, and not to eat.</td>', 'My wife would love that bunny, and not to eat.', '2005-03-02 01:29:09.000000', NULL, 1),
(1202352, 151475, 16241, '<td valign="top">pink on white is always great</td>', 'pink on white is always great', '2005-03-02 01:29:17.000000', NULL, 1),
(1202354, 150406, 17507, '<td valign="top">Ah, the bird of paradise! Nicely captured.</td>', 'Ah, the bird of paradise! Nicely captured.', '2005-03-02 01:29:46.000000', NULL, 1),
(1202355, 151320, 16241, '<td valign="top">beautiful</td>', 'beautiful', '2005-03-02 01:30:07.000000', NULL, 1),
