(1202357, 151373, 16241, '<td valign="top">cute</td>', 'cute', '2005-03-02 01:30:27.000000', NULL, 1),
(1202358, 151341, 18367, '<td valign="top">This is very nice indeed.  Too bad about the shadows.... they tend to detract from the photo, particularly that portion covering the right shoulder.  This is my highest scoring pic so far.... I will be back........</td>', 'This is very nice indeed.  Too bad about the shadows.... they tend to detract from the photo, particularly that portion covering the right shoulder.  This is my highest scoring pic so far.... I will be back........', '2005-03-02 01:31:09.000000', NULL, 1),
(1202359, 150682, 17507, '<td valign="top">Haven''t seen a whole lot of pictures yet, but this one I like better than the others I''ve seen. A very nice dynamic capture.</td>', 'Haven''t seen a whole lot of pictures yet, but this one I like better than the others I''ve seen. A very nice dynamic capture.', '2005-03-02 01:31:38.000000', NULL, 1),
(1202360, 151372, 17507, '<td valign="top">Hmm, this seems more to me like "white on light" than "light on white," but I like it anyway. Couldn''t guess where this might be in the world except Iceland or Yellowstone, but that probably does nothing but show my provincialism. Great shot.</td>', 'Hmm, this seems more to me like "white on light" than "light on white," but I like it anyway. Couldn''t guess where this might be in the world except Iceland or Yellowstone, but that probably does nothing but show my provincialism. Great shot.', '2005-03-02 01:32:47.000000', NULL, 1),
(1202361, 151629, 33182, '<td valign="top">ROTFLMAO. Thanks for the laugh. Aint it true though?</td>', 'ROTFLMAO. Thanks for the laugh. Aint it true though?', '2005-03-02 01:32:47.000000', NULL, 1),
(1202362, 150291, 16241, '<td valign="top">i smell a ribbon</td>', 'i smell a ribbon', '2005-03-02 01:32:59.000000', NULL, 1),
