(1204809, 151838, 33542, '<td valign="top">interesting idea, but I think parts are over exposed... maybe less midtone contrast?</td>', 'interesting idea, but I think parts are over exposed... maybe less midtone contrast?', '2005-03-03 00:43:51.000000', NULL, 1),
(1204810, 150491, 31637, '<td valign="top">fuzzy..nice try though</td>', 'fuzzy..nice try though', '2005-03-03 00:43:55.000000', NULL, 1),
