INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1205716, 151456, 10275, '<td valign="top">I bet this will be a ribbon contender. I love the way the focus recedes. Cool stock imagery. Nice tight crop. 10</td>', 'I bet this will be a ribbon contender. I love the way the focus recedes. Cool stock imagery. Nice tight crop. 10', '2005-03-03 14:29:43.000000', NULL, 1),
(1205719, 151488, 33498, '<td valign="top">Perfect composition. Great color choices. Outstanding shot. Definitely a 10.</td>', 'Perfect composition. Great color choices. Outstanding shot. Definitely a 10.', '2005-03-03 14:30:27.000000', NULL, 1),
(1205721, 151860, 10275, '<td valign="top">A different take on this challenge, but equally effective. Very well lit, not overexposed. Beautiful image to look at. 10<br/> <br/>p.s. the border could have been a bit thinner - it is quite strong when it''s this wide.</td>', 'A different take on this challenge, but equally effective. Very well lit, not overexposed. Beautiful image to look at. 10 p.s. the border could have been a bit thinner - it is quite strong when it''s this wide.', '2005-03-03 14:31:07.000000', NULL, 1),
(1205722, 151759, 33498, '<td valign="top">Witty!</td>', 'Witty!', '2005-03-03 14:31:16.000000', NULL, 1),
(1205723, 149789, 11270, '<td valign="top">Not sure on the thick border. I am not normally against borders, I just think your eyes are drawn to the huge blackness, rather than the light coloured eggs.</td>', 'Not sure on the thick border. I am not normally against borders, I just think your eyes are drawn to the huge blackness, rather than the light coloured eggs.', '2005-03-03 14:31:24.000000', NULL, 1),
(1205725, 151865, 10275, '<td valign="top">Cool idea. It''s very well lit and executed. Not overexposed. Nice and smooth. Love the angle too. 10</td>', 'Cool idea. It''s very well lit and executed. Not overexposed. Nice and smooth. Love the angle too. 10', '2005-03-03 14:31:51.000000', NULL, 1),
(1205727, 150618, 10275, '<td valign="top">This is very cool image. Great sharpness and DOF. Nice composition. The only thing is that it has a yellow cast. I actually copied it to my computer and coverted it to b&amp;w to see what it would look like. Try it and you will see a huge difference - it looks much whiter and more pleasing. With all that said, I still love this shot. 10</td>', 'This is very cool image. Great sharpness and DOF. Nice composition. The only thing is that it has a yellow cast. I actually copied it to my computer and coverted it to b&w to see what it would look like. Try it and you will see a huge difference - it looks much whiter and more pleasing. With all that said, I still love this shot. 10', '2005-03-03 14:33:55.000000', NULL, 1),
(1205729, 151371, 33498, '<td valign="top">Very subtle. Very spare. In this case: Less Is Better. You get a 10 from me.</td>', 'Very subtle. Very spare. In this case: Less Is Better. You get a 10 from me.', '2005-03-03 14:34:14.000000', NULL, 1),
