INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1206730, 150816, 8624, '<td valign="top">I think this might have been a cool high key shot in color the gumball machine would have looked nice against the white background and her white dress. why did you convert it to black and white?</td>', 'I think this might have been a cool high key shot in color the gumball machine would have looked nice against the white background and her white dress. why did you convert it to black and white?', '2005-03-03 22:28:02.000000', NULL, 1),
(1206733, 150269, 8624, '<td valign="top">nice lighting, but I don''t care for the arrangement. The ball on the tee looks like it is just floating behind the other ball. doesn''t look natural</td>', 'nice lighting, but I don''t care for the arrangement. The ball on the tee looks like it is just floating behind the other ball. doesn''t look natural', '2005-03-03 22:30:58.000000', NULL, 1),
(1206739, 151629, 18868, '<td valign="top">A beatifully lit, technically outsanding, yet inexplicably riveting and bizarre photo.</td>', 'A beatifully lit, technically outsanding, yet inexplicably riveting and bizarre photo.', '2005-03-03 22:43:48.000000', NULL, 1),
(1206740, 151501, 18868, '<td valign="top">really really nicely lit, darn shame about the top edge.</td>', 'really really nicely lit, darn shame about the top edge.', '2005-03-03 22:45:56.000000', NULL, 1),
(1206743, 151728, 5475, '<td valign="top">I think we have a winner!  I predict you will take the blue!  I hope I''m right, as I believe this is better than any other shot in the challenge by leaps and bounds!  You have a couple of dust spots on your sensor, but with basic editing, you can''t really do much.  10 from me!<br/>JD</td>', 'I think we have a winner!  I predict you will take the blue!  I hope I''m right, as I believe this is better than any other shot in the challenge by leaps and bounds!  You have a couple of dust spots on your sensor, but with basic editing, you can''t really do much.  10 from me!JD', '2005-03-03 22:49:35.000000', NULL, 1),
(1206744, 151830, 34069, '<td valign="top">Creative background that is obviously white but not just a blank wall.  The right side of the vase looks ever so slightly blown out but all in all an excellent shot.  9</td>', 'Creative background that is obviously white but not just a blank wall.  The right side of the vase looks ever so slightly blown out but all in all an excellent shot.  9', '2005-03-03 22:50:04.000000', NULL, 1),
(1206745, 150346, 34069, '<td valign="top">Background is a bit dark but I guess it was originally white.  I definitely like the subject and the composition. 9.</td>', 'Background is a bit dark but I guess it was originally white.  I definitely like the subject and the composition. 9.', '2005-03-03 22:50:32.000000', NULL, 1),
(1206746, 151876, 34069, '<td valign="top">Good expression on the dog, nice capture of the snack in midair, excellent slobber!   And you stuck to the letter of the challenge with a pure white background and a very light subject that is not overexposed.  My favorite of this challenge and my only 10.</td>', 'Good expression on the dog, nice capture of the snack in midair, excellent slobber!   And you stuck to the letter of the challenge with a pure white background and a very light subject that is not overexposed.  My favorite of this challenge and my only 10.', '2005-03-03 22:51:23.000000', NULL, 1),
(1206750, 150763, 18868, '<td valign="top">Very nicely lit!  I''d bet you find this in the top 20.</td>', 'Very nicely lit!  I''d bet you find this in the top 20.', '2005-03-03 22:54:29.000000', NULL, 1),
(1206753, 151826, 34396, '<td valign="top">I would have liked this photo even more if the ground had been without all of the criss crossing tracks.  However, I suppose the tracks also add to the shadow and texture of the photo.</td>', 'I would have liked this photo even more if the ground had been without all of the criss crossing tracks.  However, I suppose the tracks also add to the shadow and texture of the photo.', '2005-03-03 22:56:34.000000', NULL, 1),
