(1211810, 150980, 15420, '<td valign="top">awesome.</td>', 'awesome.', '2005-03-07 04:16:29.000000', NULL, 1),
(1211825, 149764, 34601, '<td valign="top">The photo would have been better if it was true to the challenge of placing the object behind a pure white background.</td>', 'The photo would have been better if it was true to the challenge of placing the object behind a pure white background.', '2005-03-07 04:29:51.000000', NULL, 1),
